sys_variable_value.value:
(function execute(inputs, outputs) {

    // ==========================================
    // 1. Get Reserved For User
    // ==========================================

    var userName = '';

    var userGR = new GlideRecord('sys_user');

    if (userGR.get(inputs.reserved_for)) {
        userName = userGR.getDisplayValue();
    } else {
        userName = inputs.reserved_for;
    }


    // ==========================================
    // 2. Get Workspace Name
    // ==========================================

    var workspaceName = '';

    var workspaceGR = new GlideRecord('x_1209398_wrm_workspace_options');

    if (workspaceGR.get(inputs.workspace_name)) {
        workspaceName = workspaceGR.getDisplayValue();
    } else {
        workspaceName = inputs.workspace_name;
    }


    // ==========================================
    // 3. Get Rejection Reason
    // ==========================================

    var rejectionReason = inputs.rejection_reason;

    if (gs.nil(rejectionReason)) {
        rejectionReason = 'No reason provided.';
    }


    // ==========================================
    // 4. Build Discord Message
    // ==========================================

    var message =
        '**Workspace Request Rejected**\n\n' +
        '**User:** ' + userName + '\n' +
        '**Workspace:** ' + workspaceName + '\n' +
        '**Reason:** ' + rejectionReason;


    // ==========================================
    // 5. Send Discord Notification
    // ==========================================

    var discord = new discordNotification();

    discord.sendMessage(message, '❌');


})(inputs, outputs);

